mapper.select:
SELECT 

WHERE a.deleted_at IS NULL

	AND a.status = CAST(#{status} AS AUCTION_STATUS)


	AND a.live_broadcast_id IS NOT NULL


	AND a.live_broadcast_id IS NULL


	AND p.category_id = #{categoryId}


	AND a.current_price >= #{minPrice}


	AND a.current_price <= #{maxPrice}


	AND a.auction_id < #{cursorId}


	ORDER BY a.ended_at ASC NULLS LAST, a.auction_id DESC
	ORDER BY a.bookmark_count DESC, a.view_count DESC, a.auction_id DESC
	ORDER BY a.current_price ASC, a.auction_id DESC
	ORDER BY a.current_price DESC, a.auction_id DESC
	ORDER BY a.bid_count DESC, a.auction_id DESC
	ORDER BY a.auction_id DESC

LIMIT #{limit}

	OFFSET #{offset}

SELECT bm.bookmark_id, 

JOIN bookmark bm ON bm.product_id = p.product_id AND bm.member_id = #{memberId}
WHERE a.deleted_at IS NULL

AND a.auction_id = (SELECT MAX(a2.auction_id) FROM auction a2 WHERE a2.product_id = p.product_id AND a2.deleted_at IS NULL)

	AND bm.bookmark_id < #{cursorId}

ORDER BY bm.bookmark_id DESC
LIMIT #{limit}
